import type { Localized } from "@/lib/i18n";
import { OPEN_SLUGS } from "@/lib/lab-open";

/**
 * Lab = 设计效果库。
 *
 * 每条 effect 对应一个**自包含的 HTML 文件** `public/effects/<slug>.html`，
 * 页面上用 <iframe> 加载。为什么必须是 iframe 而不是直接渲染进页面：
 * 本站没有 Tailwind、全局选择器很多（`* {}`、裸 `a {}`、裸 `footer {}`…），
 * 从别处扒来的效果代码一旦进主文档，两边会互相污染，而且是**一边好一边坏**
 * 那种难查的污染。iframe 给每条效果一个干净的文档，代价只是一次 HTTP 请求。
 *
 * 🩸 **代码不写在这个文件里**：详情页展示的源码是构建时从
 *    `public/effects/<slug>.html` 读出来的（见 `lib/effect-source.ts`）。
 *    在这里再抄一份 = 两处真相，改了 demo 忘了改展示，页面上给的代码就是错的。
 */

export type CategoryId = "web-effects" | "border-effects" | "icon-morph" | "animated-icons" | "widgets" | "dashboard" | "creative" | "mobile-ui";

export interface Category {
  id: CategoryId;
  title: Localized;
  /** 分类页的引子，也进 <meta description> */
  intro: Localized;
  /** 分类的强调色，用在标题的圆点与卡片底 */
  accent: string;
  /**
   * 分类页里的小组（按这里的顺序分段显示，顶部一排锚点）。
   * 给了 groups 的分类，**每一条效果都必须有其中一个 group**，否则构建直接报错
   * （见 effectGroups）—— 漏分组的卡片会凭空消失在页面上，比报错难发现得多。
   */
  groups?: { id: string; title: Localized }[];
}

