export function effectsIn(category: CategoryId): Effect[] {
  return effects
    .filter((e) => e.category === category)
    .sort((a, b) => {
      // 置顶的在前（pin 小的更前），其余按日期倒序
      const pa = a.pin ?? Infinity, pb = b.pin ?? Infinity;
      if (pa !== pb) return pa - pb;
      // 同一天的按数组顺序：主样板写在前面就排在前面（之前平局返回 -1，同日会整批倒序）
      return a.date === b.date ? 0 : a.date < b.date ? 1 : -1;
    });
}

/**
 * 分类页按小组分段。分类没给 groups 就返回 null（整页一个网格）。
 * 🩸有 groups 时每条都必须落进某一组：落不进的直接抛错让构建红，
 * 而不是悄悄从页面上消失。
 */
export function effectGroups(category: CategoryId): { id: string; title: Localized; items: Effect[] }[] | null {
  const cat = categoryById(category);
  if (!cat?.groups) return null;
  const items = effectsIn(category);
  const ids = new Set(cat.groups.map((g) => g.id));
  const stray = items.filter((e) => !e.group || !ids.has(e.group));
  if (stray.length) {
    throw new Error(`[lab] ${category}: no valid group for ${stray.map((e) => e.slug).join(", ")}`);
  }
  return cat.groups
    .map((g) => ({ id: g.id, title: g.title, items: items.filter((e) => e.group === g.id) }))
    .filter((g) => g.items.length > 0);
}

/** 没有效果的分类不出现在 /lab 上 —— 空分类页比没有分类页更伤。 */
export function activeCategories(): Category[] {
  return categories.filter((c) => effectsIn(c.id).length > 0);
}

export function categoryById(id: string): Category | undefined {
  return categories.find((c) => c.id === id);
}

export function effectBySlug(category: string, slug: string): Effect | undefined {
  return effects.find((e) => e.category === category && e.slug === slug);
}

/** demo 文件路径由 slug 推导，不在数据里手写 —— 手写就会有拼错的那天。 */
export function demoPath(e: Effect): string {
  return e.bundleDir ? `/effects/${e.slug}/index.html` : `/effects/${e.slug}.html`;
}

/**
 * 橱窗视频与海报（scripts/record-lab-videos.mjs 录的，public/lab-video/）。
 * 公开页用它代替 iframe：看得到效果、拿不到代码。
 */
export function videoPath(e: Effect): string {
  return `/lab-video/${e.slug}.mp4`;
}
export function posterPath(e: Effect): string {
  return `/lab-video/${e.slug}.jpg`;
}

/** 完整公开的那几条（lib/lab-open.ts 的 OPEN_SLUGS）：demo 可碰、代码提示词都给。 */
export function isOpen(e: Effect): boolean {
  return OPEN_SLUGS.includes(e.slug);
}

